import { describe, expect, it } from "vitest";
import { normalize } from "../../src/domain/normalize.js";

// Reference outputs generated by running the live utils.py normalize()
// against the same inputs (see conversation history / commit message).
describe("domain/normalize parity with Python utils.normalize", () => {
  const cases: [string, string][] = [
    ["a Warden Truck", "warden truck"],
    ["the Colonial Tank", "colonial tank"],
    ["tanks", "tank"],
    ["Bunkers", "bunker"],
    ["geese", "goose"],
    ["houses", "house"],
    ["DAE 3b-2 Hades Net", "dae 3b2 hade net"],
  ];

  it.each(cases)("normalize(%j) === %j", (input, expected) => {
    expect(normalize(input)).toBe(expected);
  });
});
